INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6011, 129911, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 1, 6, 11, 6, 0, 0.8, 0, 0);
